INSERT INTO delay_reasons (reason_id, code, category, description, created_at) VALUES ('RZN-001', 'WEATHER_DISRUPTION', 'ENVIRONMENTAL', 'Severe weather conditions (snowstorm, blizzard, heavy flooding, high winds) slowing transit or grounding flights.', '2026-06-01T00:00:00');
INSERT INTO delay_reasons (reason_id, code, category, description, created_at) VALUES ('RZN-002', 'FACILITY_CONGESTION', 'OPERATIONAL', 'Inbound dock queue backlog or sorting facility capacity overload exceeding operational threshold.', '2026-06-01T00:00:00');
INSERT INTO delay_reasons (reason_id, code, category, description, created_at) VALUES ('RZN-003', 'CARRIER_PERFORMANCE', 'CARRIER', 'Carrier mechanical breakdown, linehaul driver shortage, or transit lane underperformance.', '2026-06-01T00:00:00');
INSERT INTO delay_reasons (reason_id, code, category, description, created_at) VALUES ('RZN-004', 'ROUTE_DEVIATION', 'OPERATIONAL', 'Detour or misdirection resulting in increased transit distance and elapsed leg duration.', '2026-06-01T00:00:00');
INSERT INTO delay_reasons (reason_id, code, category, description, created_at) VALUES ('RZN-005', 'DELAYED_SCANS', 'DATA_QUALITY', 'Telemetry scan batching or delayed EDI transmission causing stale visibility in transit status.', '2026-06-01T00:00:00');
INSERT INTO delay_reasons (reason_id, code, category, description, created_at) VALUES ('RZN-006', 'MISSED_FACILITY_CUTOFF', 'OPERATIONAL', 'Shipment arrived at facility after daily outbound sorting cutoff time, holding package until next cycle.', '2026-06-01T00:00:00');
INSERT INTO delay_reasons (reason_id, code, category, description, created_at) VALUES ('RZN-007', 'OPERATIONAL_HANDLING_DELAY', 'OPERATIONAL', 'Damaged barcode re-labeling, hazmat inspection, or custom manual audit requirement.', '2026-06-01T00:00:00');
INSERT INTO delay_reasons (reason_id, code, category, description, created_at) VALUES ('RZN-008', 'UNKNOWN', 'OTHER', 'Unclassified anomaly or missing sensor telemetry explanation.', '2026-06-01T00:00:00');
